
const KEY={health:'nutt_health_metrics',cal:'nutt_femboy_cal',chat:'nutt_chat_logs',projects:'nutt_projects',workouts:'nutt_workouts',settings:'nutt_settings',media:'nutt_media_history'};
const $=id=>document.getElementById(id);
const load=(k,d)=>{try{return JSON.parse(localStorage.getItem(k))??d}catch{return d}};
const save=(k,v)=>localStorage.setItem(k,JSON.stringify(v));
function toast(msg){let t=$('toast');if(!t)return;t.textContent=msg;t.classList.add('show');clearTimeout(window._toast);window._toast=setTimeout(()=>t.classList.remove('show'),2200)}
function todayKey(){let d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}

// --- Friendly confirmation modal (replaces native browser confirm dialogs) ---
function ensureConfirmModal(){
  if(document.getElementById('friendlyConfirm')) return;
  const wrap=document.createElement('div');
  wrap.id='friendlyConfirm';
  wrap.className='confirm-overlay';
  wrap.hidden=true;
  wrap.innerHTML=`
    <div class="confirm-modal" role="dialog" aria-modal="true" aria-labelledby="confirmTitle" aria-describedby="confirmMessage">
      <button class="confirm-close" type="button" aria-label="ปิด">×</button>
      <div class="confirm-icon" aria-hidden="true">💕</div>
      <div class="confirm-title" id="confirmTitle">ขอถามนิดหนึ่งนะ</div>
      <div class="confirm-message" id="confirmMessage"></div>
      <div class="confirm-actions">
        <button class="btn ghost confirm-cancel" type="button">ยกเลิก</button>
        <button class="btn confirm-ok" type="button">ตกลง</button>
      </div>
    </div>`;
  document.body.appendChild(wrap);
  const close=()=>{if(wrap._resolve)wrap._resolve(false);wrap.hidden=true;wrap._resolve=null};
  wrap.querySelector('.confirm-close').onclick=close;
  wrap.querySelector('.confirm-cancel').onclick=close;
  wrap.querySelector('.confirm-ok').onclick=()=>{if(wrap._resolve)wrap._resolve(true);wrap.hidden=true;wrap._resolve=null};
  wrap.addEventListener('click',e=>{if(e.target===wrap)close()});
  document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!wrap.hidden)close()});
}
function friendlyConfirm(message,{title='ขอถามนิดหนึ่งนะ',ok='ตกลง',cancel='ยกเลิก',icon='💕'}={}){
  ensureConfirmModal();
  const wrap=document.getElementById('friendlyConfirm');
  wrap.querySelector('.confirm-title').textContent=title;
  wrap.querySelector('.confirm-message').textContent=message;
  wrap.querySelector('.confirm-ok').textContent=ok;
  wrap.querySelector('.confirm-cancel').textContent=cancel;
  wrap.querySelector('.confirm-icon').textContent=icon;
  wrap.hidden=false;
  requestAnimationFrame(()=>wrap.classList.add('show'));
  return new Promise(resolve=>{wrap._resolve=value=>{wrap.classList.remove('show');resolve(value)};wrap.querySelector('.confirm-ok').focus()});
}

function pageInit(){
  const p=document.body.dataset.page;
  if($('chatTime') && typeof initCompanionChat==='function') initCompanionChat();
  if(p==='dashboard') dashboard();
  if(p==='calculator') calculatorLoad();
  if(p==='workout') workoutLoad();
  if(p==='calendar') calendarInit();
  if(p==='portfolio') portfolioLoad();
  if(p==='settings') settingsLoad();
}
document.addEventListener('DOMContentLoaded',()=>{ensureConfirmModal();pageInit()});

