function logChat(title,text){let logs=load(KEY.chat,[]), stamp=new Date();let id=stamp.toISOString().slice(0,16);if(logs[0]?.id===id)return;logs.unshift({id,title,date:stamp.toLocaleDateString('th-TH'),time:stamp.toLocaleTimeString('th-TH',{hour:'2-digit',minute:'2-digit'}),text});save(KEY.chat,logs.slice(0,30))}
