function renderWorkoutSummary(){let box=$('workoutSummary');if(!box)return;let d=load(KEY.workouts,{})[todayKey()]||{},n=Object.keys(d).filter(k=>k!=='updatedAt'&&d[k]).length,r=load(KEY.media,{}).workout?.[todayKey()];box.innerHTML=`<div class="notice"><b>สรุปวันนี้</b><br>ทำสำเร็จ ${n}/4 ท่า ${r?.driveUrl?'· ☁️ อัปโหลด Drive แล้ว':''}<br><span class="sub">${r?.time?`บันทึกเมื่อ ${r.time}`:'เช็กให้ครบแล้วค่อยกดบันทึกผลด้านล่าง'}</span></div>`}
function imageThumb(file){return new Promise((resolve,reject)=>{if(!file)return resolve('');let r=new FileReader();r.onload=()=>{let im=new Image();im.onload=()=>{let scale=Math.min(1,600/im.width,600/im.height),c=document.createElement('canvas');c.width=Math.round(im.width*scale);c.height=Math.round(im.height*scale);c.getContext('2d').drawImage(im,0,0,c.width,c.height);resolve(c.toDataURL('image/jpeg',.72))};im.onerror=reject;im.src=r.result};r.onerror=reject;r.readAsDataURL(file)})}
function fileToBase64(file){return new Promise((resolve,reject)=>{if(!file)return resolve('');let r=new FileReader();r.onload=()=>resolve(String(r.result).split(',')[1]||'');r.onerror=reject;r.readAsDataURL(file)})}
async function saveWorkoutRecord(){let d=load(KEY.workouts,{})[todayKey()]||{},n=Object.keys(d).filter(k=>k!=='updatedAt'&&d[k]).length;if(n<1)return toast('เลือกท่าอย่างน้อย 1 ท่าก่อนนะ 💕');let file=$('workoutPhoto')?.files?.[0];if(file&&file.size>25*1024*1024)return toast('รูปต้องไม่เกิน 25 MB');let note=$('workoutNote')?.value.trim()||'';let now=new Date(),thumb=file?await imageThumb(file):'',rec={date:todayKey(),iso:now.toISOString(),time:now.toLocaleTimeString('th-TH',{hour:'2-digit',minute:'2-digit',second:'2-digit'}),completed:n,exercises:workouts.filter(x=>d[x[0]]).map(x=>x[1]),note,photoName:file?.name||'',photoThumb:thumb,driveUrl:''};let settings=getSettings();if(settings.workoutDriveUrl&&file){toast('กำลังอัปโหลดรูปไป Google Drive...');try{let w=window.open('', '_blank');let b64=await fileToBase64(file);let payload={type:'workout',date:rec.date,time:rec.time,note,completed:n,fileName:file.name,mimeType:file.type||'application/octet-stream',base64:b64};let f=document.createElement('form');f.method='POST';f.action=settings.workoutDriveUrl;f.target=w.name;let inp=document.createElement('input');inp.type='hidden';inp.name='payload';inp.value=JSON.stringify(payload);f.appendChild(inp);document.body.appendChild(f);f.submit();f.remove();rec.driveUrl='submitted';}catch(e){toast('อัปโหลดไม่สำเร็จ แต่บันทึกประวัติในเครื่องแล้ว')}}else if(settings.workoutDriveUrl&&!file){toast('ยังไม่ได้เลือกรูป ระบบจะบันทึกเฉพาะประวัติในเครื่อง');}let all=load(KEY.media,{workout:{},project:{}});all.workout=all.workout||{};all.workout[todayKey()]=rec;save(KEY.media,all);$('workoutNote').value='';if($('workoutPhoto'))$('workoutPhoto').value='';renderWorkoutSummary();toast('บันทึกผลวันนี้แล้ว 💕');}
