function renderCalendar(){
 let y=calDate.getFullYear(),m=calDate.getMonth(),months=['มกราคม','กุมภาพันธ์','มีนาคม','เมษายน','พฤษภาคม','มิถุนายน','กรกฎาคม','สิงหาคม','กันยายน','ตุลาคม','พฤศจิกายน','ธันวาคม'];$('monthTitle').textContent=`${months[m]} ${y+543}`;
 let grid=$('calendar'),days=new Date(y,m+1,0).getDate(),first=new Date(y,m,1).getDay(),hist=load(KEY.cal,{}),w=load(KEY.workouts,{});
 grid.innerHTML=['อา','จ','อ','พ','พฤ','ศ','ส'].map(x=>`<div class="weekday">${x}</div>`).join('');
 for(let i=0;i<first;i++)grid.innerHTML+='<div class="day empty"></div>';
 for(let d=1;d<=days;d++){let k=`${y}-${String(m+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`,r=hist[k]||{},rec=load(KEY.media,{}).workout?.[k],done=Object.keys(w[k]||{}).filter(x=>x!=='updatedAt'&&w[k][x]).length;grid.innerHTML+=`<div class="day ${k===todayKey()?'today ':''}${r.note?'busy':''}" onclick="selectDay('${k}')"><div class="daynum">${d}</div>${r.note?`<div class="daynote">📌 ${esc(r.note)}</div>`:''}${rec?`<div class="done-dot">📷 บันทึกแล้ว</div>`:''}${done?`<div class="done-dot">♥ ${done}/4</div>`:''}</div>`}
}
function selectDay(k){selected=k;let h=load(KEY.cal,{}),w=load(KEY.workouts,{}),m=load(KEY.media,{}),r=h[k]||{},rec=m.workout?.[k],done=Object.keys(w[k]||{}).filter(x=>x!=='updatedAt'&&w[k][x]).length;$('detail').hidden=false;$('selectedDate').textContent=k;$('note').value=r.note||'';let ex=rec?.exercises?.length?rec.exercises.join(' · '):'ยังไม่มีรายการท่าที่บันทึก';$('detailText').innerHTML=`<b>📜 ประวัติวันนั้น</b><br>${rec?`💪 ทำสำเร็จ ${rec.completed}/4 ท่า<br>🕐 เวลา ${esc(rec.time)}<br>🏋️ ${esc(ex)}<br>${rec.note?`📝 ${esc(rec.note)}<br>`:''}${rec.photoThumb?`<div style="margin-top:10px"><img src="${rec.photoThumb}" style="max-width:280px;width:100%;border-radius:14px;border:1px solid var(--border)" alt="บันทึกหลังออกกำลังกาย"></div>`:''}${rec.driveUrl?`<p style="margin-top:8px">☁️ <b>ส่ง Google Drive แล้ว</b></p>`:''}`:`💪 ${done?`เช็กไว้ ${done}/4 ท่า แต่ยังไม่ได้กดบันทึกผล`:'ยังไม่มีประวัติออกกำลังกายวันนี้'}`}`;$('detail').scrollIntoView({behavior:'smooth',block:'nearest'})}
