async function addProject(e){e.preventDefault();let image=$('projImage')?.files?.[0],file=$('projFile')?.files?.[0];if(image&&image.size>25*1024*1024)return toast('รูปต้องไม่เกิน 25 MB');if(file&&file.size>50*1024*1024)return toast('ไฟล์ Project ต้องไม่เกิน 50 MB');let now=new Date(),p={id:crypto.randomUUID?.()||Date.now().toString(),title:$('projTitle').value.trim(),tag:$('projTag').value.trim(),desc:$('projDesc').value.trim(),createdAt:now.toISOString(),time:now.toLocaleString('th-TH',{timeZone:'Asia/Bangkok'})};let settings=getSettings();if(settings.projectDriveUrl&&(image||file)){toast('กำลังส่งไฟล์ไป Google Drive...');let w=window.open('', '_blank');let payloads=[];for(const f of [image,file].filter(Boolean)){payloads.push({fileName:f.name,mimeType:f.type||'application/octet-stream',base64:await fileToBase64(f)})}let payload={type:'project',date:todayKey(),time:now.toLocaleTimeString('th-TH',{hour:'2-digit',minute:'2-digit',second:'2-digit'}),title:p.title,tag:p.tag,desc:p.desc,files:payloads};try{let f=document.createElement('form');f.method='POST';f.action=settings.projectDriveUrl;f.target=w.name;let inp=document.createElement('input');inp.type='hidden';inp.name='payload';inp.value=JSON.stringify(payload);f.appendChild(inp);document.body.appendChild(f);f.submit();f.remove();p.driveUrl='submitted';}catch{toast('ส่ง Google Drive ไม่สำเร็จ แต่จะเก็บโปรเจกต์ไว้ในเครื่อง')}}projects.unshift(p);save(KEY.projects,projects);e.target.reset();renderProjects();toast('เพิ่มโปรเจกต์แล้ว 💻💕')}
function renderProjects(){let g=$('projects');g.innerHTML=projects.length?projects.map(p=>`<article class="project"><div style="display:flex;justify-content:space-between;gap:8px"><h3>${esc(p.title)}</h3><span class="tag">${esc(p.tag)}</span></div><p>${esc(p.desc)}</p><button class="btn danger" onclick="deleteProject('${p.id}')">ลบ</button></article>`).join(''):'<div class="empty">ยังไม่มีผลงาน ลองเพิ่มโปรเจกต์แรกของคุณดูนะ ✨</div>'}
async function deleteProject(id){if(!await friendlyConfirm(`โปรเจกต์นี้จะถูกลบออกจากรายการในเครื่องนี้นะ\n\nถ้าแน่ใจแล้วค่อยกดลบได้เลย เคะรออยู่ตรงนี้ 💕`, {title:'ลบโปรเจกต์นี้ไหม?',ok:'ลบโปรเจกต์',cancel:'เก็บไว้',icon:'🗑️'}))return;projects=projects.filter(p=>p.id!==id);save(KEY.projects,projects);renderProjects();toast('ลบแล้ว')}
function exportExcel(){if(typeof XLSX==='undefined')return toast('ไม่พบระบบ Excel กรุณาเปิดอินเทอร์เน็ตครั้งแรก');let wb=XLSX.utils.book_new(),h=load(KEY.health,null),cal=load(KEY.cal,{}),w=load(KEY.workouts,{}),p=load(KEY.projects,[]),c=load(KEY.chat,[]);
 let health=h?[h]:[];XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(health.length?health:[{ข้อมูล:'ไม่มีข้อมูล'}]),'สุขภาพ');
 let rows=Object.keys({...cal,...w}).sort().map(k=>({วันที่:k,นัดหมาย:cal[k]?.note||'',ออกกำลังกาย:Object.keys(w[k]||{}).filter(x=>x!=='updatedAt'&&w[k][x]).length+'/4'}));XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(rows.length?rows:[{ข้อมูล:'ไม่มีข้อมูล'}]),'ตารางและออกกำลังกาย');
 XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(p.length?p:[{ข้อมูล:'ไม่มีโปรเจกต์'}]),'พอร์ต IT');
 XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(c.length?c:[{ข้อมูล:'ไม่มีประวัติแชท'}]),'แชท');
 XLSX.writeFile(wb,`NUTT_Dashboard_${todayKey()}.xlsx`);toast('สร้างไฟล์ Excel แล้ว 📊')}
function backup(){let data={health:load(KEY.health,null),calendar:load(KEY.cal,{}),workouts:load(KEY.workouts,{}),projects:load(KEY.projects,[]),chat:load(KEY.chat,[]),settings:load(KEY.settings,{}),media:load(KEY.media,{})};let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.download=`NUTT_Backup_${todayKey()}.json`;a.click();URL.revokeObjectURL(a.href)}
function restore(file){let r=new FileReader();r.onload=()=>{try{let d=JSON.parse(r.result);if(d.health)save(KEY.health,d.health);if(d.calendar)save(KEY.cal,d.calendar);if(d.workouts)save(KEY.workouts,d.workouts);if(d.projects)save(KEY.projects,d.projects);if(d.chat)save(KEY.chat,d.chat);if(d.settings)save(KEY.settings,d.settings);if(d.media)save(KEY.media,d.media);toast('กู้คืนข้อมูลสำเร็จ');setTimeout(()=>location.reload(),700)}catch{toast('ไฟล์สำรองไม่ถูกต้อง')}};r.readAsText(file)}
async function clearAll(){if(!await friendlyConfirm(`ข้อมูลทั้งหมดของเว็บไซต์ในเครื่องนี้จะถูกลบ ได้แก่ สุขภาพ การออกกำลังกาย ปฏิทิน ข้อความ โปรเจกต์ และการตั้งค่า\n\nการกระทำนี้ไม่สามารถย้อนกลับได้ เคะขอให้เช็กอีกครั้งก่อนนะ 🥺`, {title:'ล้างข้อมูลทั้งหมด?',ok:'ล้างข้อมูลทั้งหมด',cancel:'ยกเลิก',icon:'⚠️'}))return;Object.values(KEY).forEach(k=>localStorage.removeItem(k));toast('ล้างข้อมูลแล้ว');setTimeout(()=>location.href='index.html',700)}
function settingsLoad(){}

// --- Companion settings + media memory ---
function getSettings(){return Object.assign({mode:'term',schoolDays:[1,2,3,4,5],morningTime:'08:00',homeTime:'17:30',workoutTime:'18:00',goodNightTime:'22:30',reminders:true,photo:true,photoCooldown:30,messageCooldown:30,photoFolder:'assets/femboy/'},load(KEY.settings,{}))}
function saveSettings(){let prev=getSettings();let v={mode:$('mode')?.value||'term',schoolDays:[...document.querySelectorAll('[data-day]:checked')].map(x=>+x.dataset.day),morningTime:$('morningTime')?.value||'08:00',homeTime:$('homeTime')?.value||'17:30',workoutTime:$('workoutTime')?.value||'18:00',goodNightTime:$('goodNightTime')?.value||'22:30',reminders:$('reminders')?.checked!==false,photo:$('photo')?.checked!==false,photoCooldown:+$('photoCooldown')?.value||30,messageCooldown:+$('messageCooldown')?.value||30,photoFolder:prev.photoFolder||'assets/femboy/'};v.workoutDriveUrl=$('workoutDriveUrl')?.value||'';v.projectDriveUrl=$('projectDriveUrl')?.value||'';save(KEY.settings,v);toast('ตั้งค่าการใช้ชีวิตแล้ว 💕')}
function settingsLoad(){let s=getSettings();if($('mode'))$('mode').value=s.mode;if($('morningTime'))$('morningTime').value=s.morningTime||'08:00';if($('homeTime'))$('homeTime').value=s.homeTime;if($('workoutTime'))$('workoutTime').value=s.workoutTime;if($('goodNightTime'))$('goodNightTime').value=s.goodNightTime;if($('reminders'))$('reminders').checked=s.reminders;if($('photo'))$('photo').checked=s.photo;if($('photoCooldown'))$('photoCooldown').value=s.photoCooldown;if($('messageCooldown'))$('messageCooldown').value=s.messageCooldown;if($('workoutDriveUrl'))$('workoutDriveUrl').value=s.workoutDriveUrl||'';if($('projectDriveUrl'))$('projectDriveUrl').value=s.projectDriveUrl||'';if($('photoFolderStatus'))$('photoFolderStatus').textContent=`กำลังใช้: ${s.photoFolder&&s.photoFolder!=='[โฟลเดอร์จากเครื่อง]'?s.photoFolder:'โฟลเดอร์จากเครื่องที่เลือกไว้'}`;document.querySelectorAll('[data-day]').forEach(x=>x.checked=s.schoolDays.includes(+x.dataset.day))}
