function uniqueMessage(kind){let logs=load(KEY.chat,[]),cut=Date.now()-getSettings().messageCooldown*86400000,used=new Set(logs.filter(x=>new Date(x.iso||0).getTime()>cut).map(x=>x.text));let a=msgPool[kind]||msgPool.home,free=a.filter(x=>!used.has(x));if(!free.length){toast('คลังข้อความหมวดนี้ถูกใช้ครบแล้วในช่วงเวลาที่ตั้งไว้ 💕');return a[Math.floor(Math.random()*a.length)]}return free[Math.floor(Math.random()*free.length)]}
function recordCompanion(kind){let text=uniqueMessage(kind),logs=load(KEY.chat,[]),now=new Date();logs.unshift({id:now.toISOString(),iso:now.toISOString(),title:kind,text,date:now.toLocaleDateString('th-TH',{timeZone:'Asia/Bangkok'}),time:now.toLocaleTimeString('th-TH',{timeZone:'Asia/Bangkok',hour:'2-digit',minute:'2-digit'})});save(KEY.chat,logs.slice(0,500));return text}
// --- Browser notifications / Thai-time schedule ---
function notifyPermission(){if(!('Notification' in window))return toast('เบราว์เซอร์นี้ไม่รองรับการแจ้งเตือน');Notification.requestPermission().then(x=>toast(x==='granted'?'เปิดการแจ้งเตือนแล้ว 🔔':'ยังไม่ได้อนุญาตการแจ้งเตือน'))}
function thaiToday(){return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Bangkok',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())}
function scheduleLoop(){if(!getSettings().reminders)return;let now=new Date(),hm=now.toLocaleTimeString('th-TH',{timeZone:'Asia/Bangkok',hour:'2-digit',minute:'2-digit',hour12:false});let s=getSettings(),day=Number(new Intl.DateTimeFormat('en-US',{timeZone:'Asia/Bangkok',weekday:'short'}).format(now));day=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].indexOf(new Intl.DateTimeFormat('en-US',{timeZone:'Asia/Bangkok',weekday:'short'}).format(now));let school=s.schoolDays.includes(day);let keys=school&&s.mode==='term'?['homeTime','workoutTime','goodNightTime']:['morningTime','workoutTime','goodNightTime'];keys.forEach(k=>{if(s[k]===hm)fireScheduled(k)});}
function fireScheduled(k){let s=getSettings(),hist=load(KEY.chat,[]),today=thaiToday(),id=today+'_'+k;if(hist.some(x=>x.scheduleId===id))return;let kind=k==='homeTime'?'home':k==='workoutTime'?'workout':k==='goodNightTime'?'night':'morning',text=recordCompanion(kind);hist=load(KEY.chat,[]);if(hist[0]){hist[0].scheduleId=id;save(KEY.chat,hist);}if('Notification'in window&&Notification.permission==='granted')new Notification('NUTT 💕',{body:text});}
