['sweet','cheer'].forEach(k=>{if(msgPool[k])msgPool[k]=msgPool[k].map((x,i)=>x+' '+longAdds[k][i%longAdds[k].length]);});

function recentPhotoNames(){const logs=load(KEY.chat,[]),cut=Date.now()-getSettings().photoCooldown*86400000;return new Set(logs.filter(x=>new Date(x.iso||0).getTime()>cut&&x.photoName).map(x=>x.photoName))}
function choosePhotoName(){let used=recentPhotoNames(),candidates=Array.from({length:122},(_,i)=>`image${i+1}.jpg`).filter(x=>!used.has(x));return (candidates.length?candidates:Array.from({length:122},(_,i)=>`image${i+1}.jpg`))[Math.floor(Math.random()*(candidates.length?candidates.length:122))]}
function setCompanionPhoto(){const img=$('chatPhoto');if(!img||getSettings().photo===false){if(img)img.hidden=true;return ''}const name=choosePhotoName();img.hidden=false;img.alt='Companion photo';img.src=`assets/femboy/${encodeURIComponent(name)}`;img.onerror=()=>{img.onerror=null;img.hidden=true};return name}
